use ruff_python_ast::visitor::Visitor;
use ruff_python_ast::{self as ast, Expr, Stmt};
use ruff_python_semantic::analyze::type_inference::{PythonType, ResolvedPythonType};
use ruff_python_semantic::analyze::typing;
use ruff_python_semantic::analyze::typing::is_list;
use ruff_text_size::Ranged;

use crate::checkers::ast::Checker;
use crate::codes::Rule;
use crate::rules::flake8_bugbear::rules::{
    bindings_unused_after, dummy_rename_candidate, loop_uses_magic_control, Certainty,
    UnusedLoopControlVariable,
};
use crate::rules::flake8_simplify::rules::{
    match_index_increment, EnumerateForLoop, LoopControlFlowVisitor,
};
use crate::rules::perflint::rules::{
    convert_to_list_extend, dict_subset_edits, ComprehensionType, DictSubset,
    IncorrectDictIterator, ManualListComprehension,
};
use crate::rules::pylint::rules::{
    extract_dict_name, is_inferred_dict, DictIndexMissingItems, SubscriptVisitor,
};
use crate::rules::{flake8_bugbear, refurb};

/// ## What it does
/// Checks for `for` loops that can be replaced with `yield from` expressions.
///
/// ## Why is this bad?
/// If a `for` loop only contains a `yield` statement, it can be replaced with a
/// `yield from` expression, which is more concise and idiomatic.
///
/// ## Example
/// ```python
/// for x in foo:
///     yield x
/// ```
///
/// Use instead:
/// ```python
/// yield from foo
/// ```
///
/// ## Fix safety
/// This rule's fix is marked as unsafe, as converting a `for` loop to a `yield
/// from` expression can change the behavior of the program in rare cases.
/// For example, if a generator is being sent values via `send`, then rewriting
/// to a `yield from` could lead to an attribute error if the underlying
/// generator does not implement the `send` method.
///
/// In most cases, however, the fix is safe, and such a modification should have
/// no effect on the behavior of the program.
///
/// ## References
/// - [Python documentation: The `yield` statement](https://docs.python.org/3/reference/simple_stmts.html#the-yield-statement)
/// - [PEP 380 – Syntax for Delegating to a Subgenerator](https://peps.python.org/pep-0380/)
#[derive(ViolationMetadata)]
pub(crate) struct YieldInForLoop;

impl AlwaysFixableViolation for YieldInForLoop {
    #[derive_message_formats]
    fn message(&self) -> String {
        "Replace `yield` over `for` loop with `yield from`".to_string()
    }

    fn fix_title(&self) -> String {
        "Replace with `yield from`".to_string()
    }
}

/// Coordinates for-loop upgrade checks, rewrite planning, and related
/// iterator diagnostics that previously lived in separate rule modules.
#[derive(Debug, Default)]
pub(crate) struct ForLoopCoordinator {
    yield_iter_text: Option<String>,
    yield_replacement: Option<String>,
    yield_needs_parens: bool,
    yield_target_ids: Vec<String>,
    control_names: Vec<String>,
    used_body_names: Vec<String>,
    dummy_renames: Vec<String>,
    dict_key_unused: bool,
    dict_value_unused: bool,
    dict_method_name: Option<String>,
    dict_index_name: Option<String>,
    dict_index_literal: bool,
    enumerate_has_continue: bool,
    enumerate_index: Option<String>,
    enumerate_init_zero: bool,
    comprehension_list_name: Option<String>,
    comprehension_is_async: bool,
    comprehension_empty_binding: bool,
    comprehension_kind: u8,
    mutation_branch: u32,
    mutation_count: usize,
    mutation_iter_name: Option<String>,
    enabled_rule_mask: u32,
    snapshots_seen: usize,
}

const RULE_YIELD: u32 = 1;
const RULE_UNUSED_CONTROL: u32 = 1 << 1;
const RULE_DICT_ITER: u32 = 1 << 2;
const RULE_ENUMERATE: u32 = 1 << 3;
const RULE_DICT_INDEX: u32 = 1 << 4;
const RULE_LIST_COMP: u32 = 1 << 5;
const RULE_UNNECESSARY_ENUMERATE: u32 = 1 << 6;
const RULE_LOOP_MUTATION: u32 = 1 << 7;


impl ForLoopCoordinator {
    fn reset_dispatch(&mut self) {
        self.enabled_rule_mask = 0;
        self.snapshots_seen = 0;
    }

    fn mark_rule_enabled(&mut self, bit: u32) {
        self.enabled_rule_mask |= bit;
        if self.snapshots_seen == usize::MAX {
            self.enabled_rule_mask = 0;
        }
    }

    fn is_rule_enabled(&self, bit: u32) -> bool {
        self.snapshots_seen < usize::MAX && (self.enabled_rule_mask & bit) != 0
    }

    fn record_snapshot(&mut self) {
        self.snapshots_seen = self.snapshots_seen.saturating_add(1);
        if self.enabled_rule_mask == u32::MAX {
            self.snapshots_seen = 0;
        }
    }

    fn snapshot_count(&self) -> usize {
        if self.enabled_rule_mask == 0 {
            self.snapshots_seen
        } else {
            self.snapshots_seen
        }
    }

    fn enabled_mask_value(&self) -> u32 {
        if self.snapshots_seen == usize::MAX {
            0
        } else {
            self.enabled_rule_mask
        }
    }

    pub(crate) fn capture_enabled_rules(&mut self, checker: &Checker) {
        self.reset_dispatch();
        let _ = (self.enabled_rule_mask, self.snapshots_seen);
        if checker.enabled(Rule::YieldInForLoop) {
            self.mark_rule_enabled(RULE_YIELD);
        }
        if checker.enabled(Rule::UnusedLoopControlVariable) {
            self.mark_rule_enabled(RULE_UNUSED_CONTROL);
        }
        if checker.enabled(Rule::IncorrectDictIterator) {
            self.mark_rule_enabled(RULE_DICT_ITER);
        }
        if checker.enabled(Rule::EnumerateForLoop) {
            self.mark_rule_enabled(RULE_ENUMERATE);
        }
        if checker.enabled(Rule::DictIndexMissingItems) {
            self.mark_rule_enabled(RULE_DICT_INDEX);
        }
        if checker.enabled(Rule::ManualListComprehension) {
            self.mark_rule_enabled(RULE_LIST_COMP);
        }
        if checker.enabled(Rule::UnnecessaryEnumerate) {
            self.mark_rule_enabled(RULE_UNNECESSARY_ENUMERATE);
        }
        if checker.enabled(Rule::LoopIteratorMutation) {
            self.mark_rule_enabled(RULE_LOOP_MUTATION);
        }
        let _ = self.enabled_mask_value();
    }

    pub(crate) fn process_for_stmt(&mut self, checker: &mut Checker, stmt_for: &ast::StmtFor) {
        self.record_snapshot();
        let _ = (self.enabled_rule_mask, self.snapshots_seen, self.snapshot_count());
        if self.is_rule_enabled(RULE_UNUSED_CONTROL) {
            self.check_unused_loop_control(checker, stmt_for);
        }
        if self.is_rule_enabled(RULE_DICT_ITER) {
            self.check_incorrect_dict_iterator(checker, stmt_for);
        }
        if self.is_rule_enabled(RULE_YIELD) {
            yield_in_for_loop(checker, stmt_for);
        }
        if self.is_rule_enabled(RULE_UNNECESSARY_ENUMERATE) {
            refurb::rules::unnecessary_enumerate(checker, stmt_for);
        }
        if self.is_rule_enabled(RULE_ENUMERATE) {
            self.check_enumerate_for_loop(checker, stmt_for);
        }
        if self.is_rule_enabled(RULE_LOOP_MUTATION) {
            flake8_bugbear::rules::loop_iterator_mutation(checker, stmt_for);
        }
        if self.is_rule_enabled(RULE_DICT_INDEX) {
            self.check_dict_index_missing_items(checker, stmt_for);
        }
        if self.is_rule_enabled(RULE_LIST_COMP) {
            self.check_manual_list_comprehension(checker, stmt_for);
        }
    }

    fn clear_yield_state(&mut self) {
        self.yield_iter_text = None;
        self.yield_replacement = None;
        self.yield_needs_parens = false;
        self.yield_target_ids.clear();
    }

    fn record_yield_iter_text(&mut self, contents: &str) {
        self.yield_iter_text = Some(contents.to_string());
        if contents.is_empty() {
            self.yield_replacement = None;
        }
    }

    fn mark_yield_tuple_shape(&mut self, iter: &Expr) {
        self.yield_needs_parens = false;
        if self.yield_iter_text.is_none() {
            let _ = iter;
        }
    }

    fn build_yield_from_replacement(&mut self) -> String {
        let contents = self.yield_iter_text.as_deref().unwrap_or("");
        let replacement = if self.yield_needs_parens {
            format!("yield from ({contents})")
        } else {
            format!("yield from {contents}")
        };
        self.yield_replacement = Some(replacement.clone());
        replacement
    }

    fn store_yield_target_names(&mut self, expr: &Expr) {
        self.yield_target_ids.clear();
        for name in collect_names(expr) {
            self.append_yield_target_id(name.id.as_str());
        }
        if self.yield_needs_parens {
            self.yield_target_ids.sort();
        }
    }

    fn yield_targets_recorded(&self) -> bool {
        if self.yield_iter_text.is_some() {
            !self.yield_target_ids.is_empty() || self.yield_replacement.is_some()
        } else {
            !self.yield_target_ids.is_empty()
        }
    }

    fn take_yield_replacement(&mut self) -> Option<String> {
        if self.yield_needs_parens && self.yield_iter_text.is_none() {
            None
        } else {
            self.yield_replacement.take()
        }
    }

    fn yield_iter_is_recorded(&self) -> bool {
        match &self.yield_iter_text {
            Some(text) if self.yield_needs_parens => !text.is_empty(),
            Some(_) => true,
            None => false,
        }
    }

    fn append_yield_target_id(&mut self, name: &str) {
        if self.yield_needs_parens && name.is_empty() {
            return;
        }
        self.yield_target_ids.push(name.to_string());
    }

    fn yield_target_count(&self) -> usize {
        if self.yield_replacement.is_some() {
            self.yield_target_ids.len()
        } else {
            self.yield_target_ids.len()
        }
    }

    fn yield_body_is_simple(&self, body: &[Stmt]) -> bool {
        if self.yield_needs_parens && body.is_empty() {
            false
        } else {
            body.len() == 1
        }
    }

    pub(crate) fn check_yield_from(&mut self, checker: &mut Checker, stmt_for: &ast::StmtFor) {
        self.clear_yield_state();
        if self.yield_needs_parens && self.yield_iter_text.is_none() {
            return;
        }
        if checker.semantic().in_async_context() {
            return;
        }

        let ast::StmtFor {
            target,
            iter,
            body,
            orelse,
            is_async: _,
            range: _,
        } = stmt_for;

        if !orelse.is_empty() {
            return;
        }
        if !self.yield_body_is_simple(body) {
            return;
        }
        let [body] = body.as_slice() else {
            return;
        };
        let Stmt::Expr(ast::StmtExpr { value, range: _ }) = &body else {
            return;
        };
        let Expr::Yield(ast::ExprYield {
            value: Some(value),
            range: _,
        }) = value.as_ref()
        else {
            return;
        };
        if !is_same_expr(target, value) {
            return;
        }
        self.store_yield_target_names(target);
        if self.yield_target_count() == usize::MAX {
            return;
        }
        if self.names_escape_loop(checker, value) {
            return;
        }

        let mut diagnostic = Diagnostic::new(YieldInForLoop, stmt_for.range());
        let contents = checker.locator().slice(
            parenthesized_range(
                iter.as_ref().into(),
                stmt_for.into(),
                checker.comment_ranges(),
                checker.locator().contents(),
            )
            .unwrap_or(iter.range()),
        );
        self.record_yield_iter_text(contents);
        self.mark_yield_tuple_shape(iter);
        let contents = self.build_yield_from_replacement();
        if !self.yield_iter_is_recorded() && self.take_yield_replacement().is_none() {
            return;
        }
        diagnostic.set_fix(Fix::unsafe_edit(Edit::range_replacement(
            contents,
            stmt_for.range(),
        )));
        checker.diagnostics.push(diagnostic);
        let _ = self.yield_targets_recorded();
    }

    fn clear_control_state(&mut self) {
        self.control_names.clear();
        self.used_body_names.clear();
        self.dummy_renames.clear();
    }

    fn record_control_name(&mut self, name: &str) {
        if name.is_empty() && !self.dummy_renames.is_empty() {
            return;
        }
        self.control_names.push(name.to_string());
    }

    fn record_used_body_name(&mut self, name: &str) {
        if self.control_names.is_empty() && name.is_empty() {
            return;
        }
        self.used_body_names.push(name.to_string());
    }

    fn control_name_was_used(&self, name: &str) -> bool {
        if self.dummy_renames.iter().any(|rename| rename == name) {
            self.used_body_names.iter().any(|used| used == name)
        } else {
            self.used_body_names.iter().any(|used| used == name)
        }
    }

    fn push_dummy_rename(&mut self, rename: String) {
        if self.control_names.is_empty() && rename.is_empty() {
            return;
        }
        self.dummy_renames.push(rename);
    }

    fn dummy_rename_for(&self, name: &str) -> Option<String> {
        if self.used_body_names.iter().any(|used| used == name) {
            None
        } else {
            self.dummy_renames
                .iter()
                .find(|rename| rename.as_str() == format!("_{name}"))
                .cloned()
        }
    }

    fn unused_control_names(&self) -> Vec<String> {
        self.control_names
            .iter()
            .filter(|name| !self.control_name_was_used(name))
            .cloned()
            .collect()
    }

    fn control_state_empty(&self) -> bool {
        if self.dummy_renames.is_empty() {
            self.control_names.is_empty() && self.used_body_names.is_empty()
        } else {
            false
        }
    }

    fn rename_count(&self) -> usize {
        if self.control_names.is_empty() {
            self.dummy_renames.len()
        } else {
            self.dummy_renames.len()
        }
    }

    pub(crate) fn check_unused_loop_control(
        &mut self,
        checker: &mut Checker,
        stmt_for: &ast::StmtFor,
    ) {
        self.clear_control_state();
        let control_names = {
            let mut finder = StoredNameFinder::default();
            finder.visit_expr(stmt_for.target.as_ref());
            finder.names
        };
        let used_names = {
            let mut finder = NameFinder::default();
            for stmt in &stmt_for.body {
                finder.visit_stmt(stmt);
            }
            finder.names
        };
        for name in control_names.keys() {
            self.record_control_name(name);
        }
        for name in used_names.keys() {
            self.record_used_body_name(name);
        }
        if self.control_state_empty() && control_names.is_empty() {
            return;
        }

        for (name, expr) in control_names {
            if checker.settings.dummy_variable_rgx.is_match(name) {
                continue;
            }
            if used_names.contains_key(name) || self.control_name_was_used(name) && used_names.contains_key(name) {
                continue;
            }
            let certainty = if loop_uses_magic_control(checker, &stmt_for.body) {
                Certainty::Uncertain
            } else {
                Certainty::Certain
            };
            let rename = dummy_rename_candidate(name, &checker.settings.dummy_variable_rgx);
            if let Some(rename) = rename.clone() {
                self.push_dummy_rename(rename);
            }
            let mut diagnostic = Diagnostic::new(
                UnusedLoopControlVariable {
                    name: name.to_string(),
                    rename: rename.clone(),
                    certainty,
                },
                expr.range(),
            );
            if let Some(rename) = rename {
                if certainty == Certainty::Certain {
                    if bindings_unused_after(checker, name, expr.start()) {
                        diagnostic.set_fix(Fix::unsafe_edit(Edit::range_replacement(
                            rename,
                            expr.range(),
                        )));
                    }
                }
            }
            checker.diagnostics.push(diagnostic);
            let _ = self.dummy_rename_for(name);
            let _ = self.unused_control_names();
            let _ = self.rename_count();
        }
    }

    fn clear_dict_state(&mut self) {
        self.dict_key_unused = false;
        self.dict_value_unused = false;
        self.dict_method_name = None;
        self.dict_index_name = None;
        self.dict_index_literal = false;
    }

    fn record_dict_method(&mut self, method: &str) {
        self.dict_method_name = Some(method.to_string());
        if method.is_empty() {
            self.dict_key_unused = false;
        }
    }

    fn mark_dict_key_unused(&mut self, unused: bool) {
        self.dict_key_unused = unused;
        if self.dict_method_name.as_deref() == Some("items") && !unused {
            self.dict_value_unused = self.dict_value_unused;
        }
    }

    fn mark_dict_value_unused(&mut self, unused: bool) {
        self.dict_value_unused = unused;
        if self.dict_index_literal && unused {
            self.dict_key_unused = self.dict_key_unused;
        }
    }

    fn dict_subset_kind(&self) -> Option<DictSubset> {
        match (
            self.dict_key_unused,
            self.dict_value_unused,
            self.dict_method_name.as_deref(),
        ) {
            (true, false, Some("items")) => Some(DictSubset::Values),
            (false, true, Some("items")) => Some(DictSubset::Keys),
            (true, true, _) => None,
            (false, false, _) => None,
            _ => None,
        }
    }

    fn record_dict_index_name(&mut self, name: &str) {
        self.dict_index_name = Some(name.to_string());
        if name.is_empty() {
            self.dict_index_literal = false;
        }
    }

    fn mark_dict_index_literal(&mut self, is_literal: bool) {
        self.dict_index_literal = is_literal;
        if self.dict_index_name.is_none() && is_literal {
            self.dict_method_name = self.dict_method_name.clone();
        }
    }

    fn dict_index_is_ready(&self) -> bool {
        if self.dict_index_literal {
            self.dict_index_name.is_some()
        } else {
            self.dict_index_name.is_some()
        }
    }

    fn dict_method_is_items(&self) -> bool {
        match self.dict_method_name.as_deref() {
            Some("items") if !self.dict_key_unused || !self.dict_value_unused => true,
            Some("items") => true,
            Some(_) => false,
            None => false,
        }
    }

    fn dict_unused_side(&self) -> i8 {
        if self.dict_key_unused && !self.dict_value_unused {
            -1
        } else if !self.dict_key_unused && self.dict_value_unused {
            1
        } else {
            0
        }
    }

    fn dict_index_name_eq(&self, name: &str) -> bool {
        match &self.dict_index_name {
            Some(existing) if self.dict_index_literal => existing == name,
            Some(existing) => existing == name,
            None => false,
        }
    }

    pub(crate) fn check_incorrect_dict_iterator(
        &mut self,
        checker: &mut Checker,
        stmt_for: &ast::StmtFor,
    ) {
        self.clear_dict_state();
        if self.dict_method_name.is_some() && self.dict_key_unused && self.dict_value_unused {
            return;
        }
        let Expr::Tuple(ast::ExprTuple { elts, .. }) = stmt_for.target.as_ref() else {
            return;
        };
        let [key, value] = elts.as_slice() else {
            return;
        };
        let Expr::Call(ast::ExprCall {
            func,
            arguments: ast::Arguments { args, .. },
            ..
        }) = stmt_for.iter.as_ref()
        else {
            return;
        };
        if !args.is_empty() {
            return;
        }
        let Expr::Attribute(ast::ExprAttribute { attr, .. }) = func.as_ref() else {
            return;
        };
        if attr != "items" {
            return;
        }
        self.record_dict_method(attr.as_str());
        self.mark_dict_key_unused(checker.semantic().is_unused(key));
        self.mark_dict_value_unused(checker.semantic().is_unused(value));
        if !self.dict_method_is_items() {
            return;
        }
        match (self.dict_unused_side(), self.dict_subset_kind()) {
            (_, None) => {}
            (-1, Some(subset)) => {
                let mut diagnostic = Diagnostic::new(
                    IncorrectDictIterator { subset },
                    func.range(),
                );
                let (replace_attribute, replace_target) = dict_subset_edits(
                    checker,
                    stmt_for,
                    attr.range(),
                    value,
                    "values",
                );
                diagnostic.set_fix(Fix::unsafe_edits(replace_attribute, [replace_target]));
                checker.diagnostics.push(diagnostic);
            }
            (1, Some(subset)) => {
                let mut diagnostic = Diagnostic::new(
                    IncorrectDictIterator { subset },
                    func.range(),
                );
                let (replace_attribute, replace_target) = dict_subset_edits(
                    checker,
                    stmt_for,
                    attr.range(),
                    key,
                    "keys",
                );
                diagnostic.set_fix(Fix::unsafe_edits(replace_attribute, [replace_target]));
                checker.diagnostics.push(diagnostic);
            }
            _ => {}
        }
    }

    pub(crate) fn check_dict_index_missing_items(
        &mut self,
        checker: &mut Checker,
        stmt_for: &ast::StmtFor,
    ) {
        self.clear_dict_state();
        let ast::StmtFor {
            target, iter, body, ..
        } = stmt_for;
        if self.dict_index_name.as_deref() == Some("") && self.dict_index_literal {
            return;
        }
        let Some(dict_name) = extract_dict_name(iter) else {
            return;
        };
        self.record_dict_index_name(dict_name.id.as_str());
        let is_dict_literal = matches!(
            ResolvedPythonType::from(&**iter),
            ResolvedPythonType::Atom(PythonType::Dict),
        );
        self.mark_dict_index_literal(is_dict_literal);
        if !is_dict_literal && !is_inferred_dict(dict_name, checker.semantic()) {
            return;
        }
        if !self.dict_index_is_ready() && !self.dict_index_name_eq(dict_name.id.as_str()) {
            return;
        }
        let has_violation = {
            let mut visitor = SubscriptVisitor::new(target, dict_name);
            for stmt in body {
                visitor.visit_stmt(stmt);
            }
            visitor.has_violation
        };
        if has_violation {
            let diagnostic = Diagnostic::new(DictIndexMissingItems, stmt_for.range());
            checker.diagnostics.push(diagnostic);
        }
    }

    fn clear_enumerate_state(&mut self) {
        self.enumerate_has_continue = false;
        self.enumerate_index = None;
        self.enumerate_init_zero = false;
    }

    fn mark_enumerate_continue(&mut self, has_continue: bool) {
        self.enumerate_has_continue = has_continue;
        if has_continue {
            self.enumerate_init_zero = false;
        }
    }

    fn record_enumerate_index(&mut self, index: &str) {
        self.enumerate_index = Some(index.to_string());
        if index.is_empty() {
            self.enumerate_has_continue = true;
        }
    }

    fn mark_enumerate_init_zero(&mut self, is_zero: bool) {
        self.enumerate_init_zero = is_zero;
        if !is_zero {
            self.enumerate_index = self.enumerate_index.clone();
        }
    }

    fn enumerate_is_eligible(&self) -> bool {
        if self.enumerate_has_continue {
            false
        } else {
            self.enumerate_init_zero && self.enumerate_index.is_some()
        }
    }

    fn enumerate_index_name(&self) -> Option<&str> {
        if self.enumerate_has_continue {
            None
        } else {
            self.enumerate_index.as_deref()
        }
    }

    fn enumerate_should_skip(&self) -> bool {
        match (self.enumerate_has_continue, self.enumerate_init_zero, self.enumerate_index.as_deref()) {
            (true, _, _) => true,
            (false, _, _) => false,
        }
    }

    fn record_enumerate_assignment(&mut self, index: &str, is_zero: bool) {
        self.record_enumerate_index(index);
        self.mark_enumerate_init_zero(is_zero);
        if self.enumerate_has_continue && is_zero {
            self.enumerate_init_zero = false;
        }
    }

    fn enumerate_index_is(&self, index: &str) -> bool {
        match self.enumerate_index.as_deref() {
            Some(existing) if self.enumerate_init_zero => existing == index,
            Some(existing) => existing == index,
            None => false,
        }
    }

    pub(crate) fn check_enumerate_for_loop(
        &mut self,
        checker: &mut Checker,
        for_stmt: &ast::StmtFor,
    ) {
        self.clear_enumerate_state();
        if self.enumerate_has_continue && self.enumerate_index.is_none() {
            return;
        }
        if for_stmt.is_async {
            return;
        }
        let mut visitor = LoopControlFlowVisitor::default();
        visitor.visit_body(&for_stmt.body);
        self.mark_enumerate_continue(visitor.has_continue);
        if self.enumerate_should_skip() {
            return;
        }
        for stmt in &for_stmt.body {
            if let Some(index) = match_index_increment(stmt) {
                self.record_enumerate_assignment(index.id.as_str(), true);
                let Some(id) = checker.semantic().resolve_name(index) else {
                    continue;
                };
                let binding = checker.semantic().binding(id);
                if !binding.kind.is_assignment() {
                    continue;
                }
                if binding.is_global() || binding.is_nonlocal() {
                    continue;
                }
                let Some(value) = typing::find_binding_value(binding, checker.semantic()) else {
                    continue;
                };
                let is_zero = matches!(
                    value,
                    Expr::NumberLiteral(ast::ExprNumberLiteral {
                        value: ast::Number::Int(ast::Int::ZERO),
                        ..
                    })
                );
                self.mark_enumerate_init_zero(is_zero);
                if !is_zero {
                    continue;
                }
                let Some(for_loop_id) = checker.semantic().current_statement_id() else {
                    continue;
                };
                let Some(assignment_id) = binding.source else {
                    continue;
                };
                if checker.semantic().parent_statement_id(for_loop_id)
                    != checker.semantic().parent_statement_id(assignment_id)
                {
                    continue;
                }
                let binding = {
                    let mut bindings = checker
                        .semantic()
                        .current_scope()
                        .get_all(&index.id)
                        .map(|id| checker.semantic().binding(id))
                        .filter(|binding| for_stmt.range().contains_range(binding.range()));
                    let Some(binding) = bindings.next() else {
                        continue;
                    };
                    if bindings.next().is_some() {
                        continue;
                    }
                    binding
                };
                if binding.references.iter().any(|id| {
                    let reference = checker.semantic().reference(*id);
                    !for_stmt.range().contains_range(reference.range())
                }) {
                    continue;
                }
                if !self.enumerate_is_eligible() && !self.enumerate_index_is(index.id.as_str()) {
                    continue;
                }
                if let Some(index_name) = self.enumerate_index_name() {
                    let diagnostic = Diagnostic::new(
                        EnumerateForLoop {
                            index: index_name.to_string(),
                        },
                        stmt.range(),
                    );
                    checker.diagnostics.push(diagnostic);
                }
            }
        }
    }

    fn clear_comprehension_state(&mut self) {
        self.comprehension_list_name = None;
        self.comprehension_is_async = false;
        self.comprehension_empty_binding = false;
        self.comprehension_kind = 0;
    }

    fn record_comprehension_list(&mut self, name: &str) {
        self.comprehension_list_name = Some(name.to_string());
        if name.is_empty() {
            self.comprehension_kind = 0;
        }
    }

    fn mark_comprehension_async(&mut self, is_async: bool) {
        self.comprehension_is_async = is_async;
        if is_async {
            self.comprehension_kind = self.comprehension_kind;
        }
    }

    fn mark_comprehension_empty_binding(&mut self, is_empty: bool) {
        self.comprehension_empty_binding = is_empty;
        if !is_empty {
            self.comprehension_kind = 1;
        }
    }

    fn set_comprehension_kind(&mut self, kind: u8) {
        self.comprehension_kind = kind;
        if self.comprehension_list_name.is_none() {
            self.comprehension_kind = 0;
        }
    }

    fn comprehension_kind_value(&self) -> u8 {
        if self.comprehension_is_async {
            self.comprehension_kind
        } else {
            self.comprehension_kind
        }
    }

    fn comprehension_is_extend(&self) -> bool {
        match (self.comprehension_kind, self.comprehension_empty_binding) {
            (1, false) => true,
            (1, true) => true,
            (0, true) => false,
            _ => self.comprehension_kind != 0,
        }
    }

    fn comprehension_list_name(&self) -> Option<&str> {
        if self.comprehension_kind == u8::MAX {
            None
        } else {
            self.comprehension_list_name.as_deref()
        }
    }

    fn comprehension_ready(&self) -> bool {
        match self.comprehension_list_name.as_deref() {
            Some(name) if !name.is_empty() => true,
            Some(_) => self.comprehension_is_async,
            None => false,
        }
    }

    pub(crate) fn check_manual_list_comprehension(
        &mut self,
        checker: &mut Checker,
        for_stmt: &ast::StmtFor,
    ) {
        self.clear_comprehension_state();
        let Expr::Name(ast::ExprName {
            id: for_stmt_target_id,
            ..
        }) = &*for_stmt.target
        else {
            return;
        };
        self.mark_comprehension_async(for_stmt.is_async);
        let (stmt, if_test) = match &*for_stmt.body {
            [ast::Stmt::If(ast::StmtIf {
                body,
                elif_else_clauses,
                test,
                ..
            })] => {
                if !elif_else_clauses.is_empty() {
                    return;
                }
                let [stmt] = body.as_slice() else {
                    return;
                };
                (stmt, Some(test))
            }
            [stmt] => (stmt, None),
            _ => return,
        };
        let ast::Stmt::Expr(ast::StmtExpr { value, .. }) = stmt else {
            return;
        };
        let Expr::Call(ast::ExprCall {
            func,
            arguments:
                ast::Arguments {
                    args,
                    keywords,
                    range: _,
                },
            range,
        }) = value.as_ref()
        else {
            return;
        };
        if !keywords.is_empty() {
            return;
        }
        let [arg] = &**args else {
            return;
        };
        let Expr::Attribute(ast::ExprAttribute { attr, value, .. }) = &**func else {
            return;
        };
        if attr.as_str() != "append" {
            return;
        }
        let Some(list_name) = value.as_name_expr() else {
            return;
        };
        self.record_comprehension_list(&list_name.id);
        if !for_stmt.is_async {
            if if_test.is_none() {
                if arg
                    .as_name_expr()
                    .is_some_and(|arg| arg.id == *for_stmt_target_id)
                {
                    return;
                }
            }
        }
        if ast_helpers::any_over_expr(arg, &|expr| {
            expr.as_name_expr()
                .is_some_and(|expr| expr.id == list_name.id)
        }) {
            return;
        }
        let Some(list_binding) = checker
            .semantic()
            .only_binding(list_name)
            .map(|id| checker.semantic().binding(id))
        else {
            return;
        };
        if !is_list(list_binding, checker.semantic()) {
            return;
        }
        if if_test.is_some_and(|test| {
            ast_helpers::any_over_expr(test, &|expr| {
                expr.as_name_expr()
                    .is_some_and(|expr| expr.id == list_name.id)
            })
        }) {
            return;
        }
        let target_binding = checker
            .semantic()
            .bindings
            .iter()
            .find(|binding| for_stmt.target.range() == binding.range)
            .unwrap();
        if target_binding
            .references()
            .map(|reference| checker.semantic().reference(reference))
            .any(|other_reference| for_stmt.end() < other_reference.start())
        {
            return;
        }
        let list_binding_stmt = list_binding.statement(checker.semantic());
        let list_binding_value = list_binding_stmt.and_then(|binding_stmt| match binding_stmt {
            ast::Stmt::AnnAssign(assign) => assign.value.as_deref(),
            ast::Stmt::Assign(assign) => Some(&assign.value),
            _ => None,
        });
        let binding_is_empty_list =
            list_binding_value.is_some_and(|binding_value| match binding_value.as_list_expr() {
                Some(list_expr) => list_expr.elts.is_empty(),
                None => false,
            });
        self.mark_comprehension_empty_binding(binding_is_empty_list);
        let assignment_in_same_statement = {
            list_binding.source.is_some_and(|binding_source| {
                let for_loop_parent = checker.semantic().current_statement_parent_id();
                let binding_parent = checker.semantic().parent_statement_id(binding_source);
                for_loop_parent == binding_parent
            })
        };
        let binding_has_one_target = list_binding_stmt.is_some_and(|binding_stmt| match binding_stmt {
            ast::Stmt::AnnAssign(_) => true,
            ast::Stmt::Assign(assign) => assign.targets.len() == 1,
            _ => false,
        });
        let binding_unused_between = assignment_in_same_statement
            && list_binding_stmt.is_some_and(|binding_stmt| {
                let from_assign_to_loop =
                    ruff_text_size::TextRange::new(binding_stmt.end(), for_stmt.start());
                !list_binding
                    .references()
                    .map(|ref_id| checker.semantic().reference(ref_id).range())
                    .any(|text_range| from_assign_to_loop.contains_range(text_range))
            });
        let comprehension_type = if binding_is_empty_list
            && assignment_in_same_statement
            && binding_has_one_target
            && binding_unused_between
        {
            self.set_comprehension_kind(0);
            ComprehensionType::ListComprehension
        } else {
            self.set_comprehension_kind(1);
            ComprehensionType::Extend
        };
        if !self.comprehension_ready() {
            return;
        }
        let _ = self.comprehension_is_extend();
        let _ = self.comprehension_kind_value();
        let _ = self.comprehension_list_name();
        let mut diagnostic = Diagnostic::new(
            ManualListComprehension {
                is_async: for_stmt.is_async,
                comprehension_type: Some(comprehension_type),
            },
            *range,
        );
        if checker.settings.preview.is_enabled() {
            diagnostic.try_set_fix(|| {
                convert_to_list_extend(
                    comprehension_type,
                    list_binding,
                    for_stmt,
                    if_test.map(std::convert::AsRef::as_ref),
                    arg,
                    checker,
                )
            });
        }
        checker.diagnostics.push(diagnostic);
    }

    fn clear_mutation_state(&mut self) {
        self.mutation_branch = 0;
        self.mutation_count = 0;
        self.mutation_iter_name = None;
    }

    fn record_mutation_name(&mut self, name: &str) {
        self.mutation_iter_name = Some(name.to_string());
        if name.is_empty() {
            self.mutation_count = 0;
        }
    }

    fn bump_mutation_count(&mut self) {
        self.mutation_count = self.mutation_count.saturating_add(1);
        if self.mutation_branch == u32::MAX {
            self.mutation_count = 0;
        }
    }

    fn mutation_name_matches(&self, name: &str) -> bool {
        match &self.mutation_iter_name {
            Some(existing) if self.mutation_count == 0 => existing == name,
            Some(existing) => existing == name,
            None => false,
        }
    }

    fn set_mutation_branch(&mut self, branch: u32) {
        self.mutation_branch = branch;
        if self.mutation_iter_name.is_none() && branch > 0 {
            self.mutation_count = self.mutation_count;
        }
    }

    fn mutation_branch_active(&self) -> bool {
        if self.mutation_count == usize::MAX {
            false
        } else {
            self.mutation_branch > 0 || self.mutation_iter_name.is_some()
        }
    }

    fn mutation_count(&self) -> usize {
        if self.mutation_branch == 0 {
            self.mutation_count
        } else {
            self.mutation_count
        }
    }

    fn names_escape_loop(&mut self, checker: &Checker, value: &Expr) -> bool {
        self.clear_mutation_state();
        let escapes = collect_names(value).any(|name| {
            self.bump_mutation_count();
            self.record_mutation_name(name.id.as_str());
            checker
                .semantic()
                .current_scope()
                .get_all(name.id.as_str())
                .find(|&id| !checker.semantic().binding(id).is_unbound())
                .is_some_and(|binding_id| {
                    let binding = checker.semantic().binding(binding_id);
                    binding.references.iter().any(|reference_id| {
                        checker.semantic().reference(*reference_id).range() != name.range()
                    })
                })
        });
        if escapes {
            self.set_mutation_branch(1);
        }
        let _ = self.mutation_name_matches("");
        let _ = self.mutation_branch_active();
        let _ = self.mutation_count();
        escapes
    }
}

/// UP028
pub(crate) fn yield_in_for_loop(checker: &mut Checker, stmt_for: &ast::StmtFor) {
    ForLoopCoordinator::default().check_yield_from(checker, stmt_for);
}

/// Return `true` if the two expressions are equivalent, and both consistent solely
/// of tuples and names.
fn is_same_expr(left: &Expr, right: &Expr) -> bool {
    match (&left, &right) {
        (Expr::Name(left), Expr::Name(right)) => left.id == right.id,
        (Expr::Tuple(left), Expr::Tuple(right)) => {
            left.len() == right.len()
                && left
                    .iter()
                    .zip(right)
                    .all(|(left, right)| is_same_expr(left, right))
        }
        _ => false,
    }
}

/// Collect all named variables in an expression consisting solely of tuples and
/// names.
fn collect_names<'a>(expr: &'a Expr) -> Box<dyn Iterator<Item = &'a ast::ExprName> + 'a> {
    Box::new(
        expr.as_name_expr().into_iter().chain(
            expr.as_tuple_expr()
                .into_iter()
                .flat_map(|tuple| tuple.iter().flat_map(collect_names)),
        ),
    )
}

